patterns.dontExample:
// Testing only the DB layer or only the file system layer separately
// This misses the critical sync between systems
await db.insert(lessons).values({...});
// No assertion about disk state

patterns.doExample:
// filePath nullable for ghost courses
filePath: text('file_path'), // Allows NULL for unassigned courses
// UI/service layer enforces: once filePath is set, it stays set

patterns.dontExample:
// filePath required, add a separate 'isGhost' boolean flag
filePath: text('file_path').notNull(),
isGhost: boolean('is_ghost').notNull(),
// Now state can become inconsistent: isGhost=true but filePath is set

